<?php require '../../../config/bootstrap.php';$u=require_auth();$p=db();if($_SERVER['REQUEST_METHOD']==='GET'){$s=$p->prepare('SELECT * FROM alerts WHERE tenant_id=? ORDER BY id DESC LIMIT 100');$s->execute([$u['tenant_id']]);json_response(['data'=>$s->fetchAll()]);}require_role($u,['owner','admin','manager','operator']);require_csrf();$d=request_json();$id=(int)($d['id']??0);if(!$id)json_response(['error'=>'id obrigatório'],422);$s=$p->prepare('UPDATE alerts SET status=?,resolved_at=IF(?="resolved",NOW(),resolved_at) WHERE id=? AND tenant_id=?');$status=$d['status']??'acknowledged';if(!in_array($status,['acknowledged','resolved'],true))json_response(['error'=>'Estado inválido'],422);$s->execute([$status,$status,$id,$u['tenant_id']]);audit($u,'update','alert',$id,['status'=>$status]);json_response(['ok'=>true]);
